def transpose_records(records):
    if not records:
        return []
    # Collect keys in order of first appearance across records
    keys = []
    seen = set()
    for rec in records:
        for k in rec:
            if k not in seen:
                seen.add(k)
                keys.append(k)
    if not keys:
        return []
    # Build [key, column] pairs preserving insertion order
    result = []
    for k in keys:
        column = [rec.get(k) for rec in records]
        result.append([k, column])
    return result
